import * as T from 'three';
import {createRoadGuard} from './xinyi-youbike-placement.js';
// Appearance sample only: .4 m grid is a rendering parameter, not a surveyed paver size.
export function paverTexture(){const size=128,data=new Uint8Array(size*size*4);for(let y=0;y<size;y++)for(let x=0;x<size;x++){const row=Math.floor(y/64),u=(x+row*32)%64,joint=u<2||y%64<2,tile=Math.floor((x+row*32)/64),noise=((x*17+y*31)%13)-6,v=joint?91:174+((tile+row)%3)*6+noise;const i=(y*size+x)*4;data[i]=v;data[i+1]=v-3;data[i+2]=v-8;data[i+3]=255;}const t=new T.DataTexture(data,size,size);t.wrapS=t.wrapT=T.RepeatWrapping;t.magFilter=T.LinearFilter;t.minFilter=T.LinearMipmapLinearFilter;t.generateMipmaps=true;t.colorSpace=T.SRGBColorSpace;t.needsUpdate=true;return t;}
export function createEocSidewalks({scene,root,features=[],laneData=null}){root.updateMatrixWorld(true);const guard=createRoadGuard(features,laneData);if(!guard.count)return null;const positions=[],uv=[],sources=[];let skipped=0;
 root.traverse(m=>{if(!m.isMesh||!['EOC frontage paved walk','EOC site paving'].some(n=>m.name.replaceAll('_',' ')===n||m.parent?.name.replaceAll('_',' ')===n))return;const p=m.geometry.attributes.position,index=m.geometry.index;
 function emit(a,b,c,depth=0){const local=[a,b,c];if(local.some(v=>v.x<63.99||v.x>72.01||v.z>8.01||v.z< -160.01)&&m.name!=='EOC frontage paved walk')return;const world=local.map(v=>v.clone().applyMatrix4(m.matrixWorld));const normal=new T.Vector3().subVectors(world[1],world[0]).cross(new T.Vector3().subVectors(world[2],world[0])).normalize();if(normal.y<.9)return;const edge=Math.max(a.distanceTo(b),b.distanceTo(c),c.distanceTo(a));if(edge>2.9&&depth<8){const ab=a.clone().add(b).multiplyScalar(.5),bc=b.clone().add(c).multiplyScalar(.5),ca=c.clone().add(a).multiplyScalar(.5);for(const tri of [[a,ab,ca],[ab,b,bc],[ca,bc,c],[ab,bc,ca]])emit(...tri,depth+1);return;}if(guard.overlap(world.map(v=>[v.x,v.z]))){skipped++;return;}for(let i=0;i<3;i++){positions.push(...world[i].toArray());uv.push(local[i].x/.8,local[i].z/.8);}}
 const before=positions.length;for(let k=0;k<(index?.count??p.count);k+=3)emit(...[0,1,2].map(i=>new T.Vector3().fromBufferAttribute(p,index?index.getX(k+i):k+i)));if(positions.length>before)sources.push(m.name);});
 if(!positions.length)return null;const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.Float32BufferAttribute(positions,3));geometry.setAttribute('uv',new T.Float32BufferAttribute(uv,2));geometry.computeVertexNormals();geometry.computeBoundingSphere();const map=paverTexture(),material=new T.MeshStandardMaterial({map,roughness:.96,polygonOffset:true,polygonOffsetFactor:-1,polygonOffsetUnits:-3,depthWrite:false});const mesh=new T.Mesh(geometry,material);mesh.name='EOC sidewalk appearance sample — dimensions unmeasured';mesh.renderOrder=1;mesh.receiveShadow=true;mesh.castShadow=false;scene.add(mesh);
 // Camera uses actual retained paving; do not relocate the actor or alter support heights.
 const center=geometry.boundingSphere.center,ray=new T.Raycaster(),eye=new T.Vector3(30,.15,3.4).applyMatrix4(root.matrixWorld),target=new T.Vector3(27,.15,3).applyMatrix4(root.matrixWorld);for(const p of [eye,target]){ray.set(new T.Vector3(p.x,10000,p.z),new T.Vector3(0,-1,0));const hit=ray.intersectObject(mesh,false)[0];p.y=hit?.point.y??center.y;}eye.y+=1.4;target.y+=.02;
 return {mesh,stats:{triangles:positions.length/9,skipped,sources,status:'appearance-sample-dimensions-unmeasured'},reviewPose:()=>({eye,target}),setVisible:v=>mesh.visible=!!v,dispose(){scene.remove(mesh);geometry.dispose();material.dispose();map.dispose();}};
}
